-- The database under ./db is autogenerated. Changing the entries there
-- will result in a data loss whenever a new database gets extracted.
-- To be able to customize and/or fix entries that aren't yet detected
-- by the extractor logic, this file here can be used to save overwrites.

-- wipes the data table and the locale table for each id in "entries" under the given category.
-- category: items, units, quests, objects
-- entries: { [id] = "Name", ... }
-- name: can be empty, only used for reference/searchability
local function remove(category, entries)
  for id in pairs(entries) do
    pfDB[category]["data-epoch"][id] = { }
    pfDB[category]["enUS-epoch"][id] = ""
  end
end

